import sys; sys.path.insert(0, '/workspace/site/scripts/guides')
from ghelp import *
GUIDES = []
A = GUIDES.append

A(mk('instagram-two-factor-lost-access',
 'Lost your Instagram two-factor codes? How to get back in',
 'Lost Instagram 2FA Codes? How to Get Back In',
 'Lost your phone or authenticator app and Instagram keeps asking for a code? Use backup codes, a logged-in device or Instagram’s official recovery flow.',
 'instagram', 'Two-factor', 'Instagram',
 'use a backup code if you saved one. If you didn’t, check whether you’re still logged in on any device, because that is the quickest route to new codes.',
 'Two-factor authentication is what stops a stranger who knows your password. It is also what locks you out when the phone that received the code is lost, broken or replaced. The fix depends on one thing: what you still have access to.',
 [('first', 'What to do first',
   '<p>Stop requesting new codes over and over. Each failed attempt can add friction, and codes that arrive late are often the ones you already triggered. Take two minutes to list what you still have:</p>'
   '<ul><li>A phone or tablet where Instagram is <strong>still logged in</strong>, even an old one.</li><li>Saved <strong>backup codes</strong> (a screenshot, a notes app, a password manager).</li><li>Access to the <strong>email address or phone number</strong> on the account.</li><li>A Facebook account linked to Instagram through Accounts Center.</li></ul>'
   '<p>Any one of these gives you a way in. If you have none, skip to Step 4.</p>'),
  ('s1', 'Step 1: Use a backup code',
   '<p>When you turned on two-factor authentication, Instagram showed a short list of backup codes. If a login code can’t be sent or you can’t reach your usual method, a backup code completes the login. Enter one when Instagram asks for a security code, then change your password and set up a new method straight away.</p>'
   '<p>Each backup code generally works once, so you may need a second one if Instagram asks you to confirm your email or phone before the 2FA prompt.</p>'),
  ('s2', 'Step 2: Check for a logged-in device',
   '<p>If Instagram is still open on an old phone, a tablet or a computer browser, you can fix this without any code. Open Accounts Center, then <em>Password and security</em>, then <em>Two-factor authentication</em>, and pick your Instagram account. Under <em>Additional methods</em> you can view or regenerate backup codes, and Instagram’s help pages also describe how to change the phone number used for text-message codes.</p>'
   '<p>Add an authentication app as a second method while you are in there. An app on your phone keeps working through a number change, and Instagram recommends it for that reason.</p>'),
  ('s3', 'Step 3: Try the Facebook route',
   '<p>If your Instagram is connected to a Facebook account in the same Accounts Center, logging in to Facebook may let you reach the same Password and security settings from there. The menu names change slightly between versions, so follow the wording on your screen rather than a screenshot from an old tutorial.</p>'),
  ('s4', 'Step 4: Use Instagram’s official recovery flow',
   '<p>With no device, no codes and no linked Facebook, go to the <strong>Forgot password?</strong> link on the login screen and ask for a login link by email or text. If you can’t reach either, use the official page at instagram.com/hacked and follow its prompts. Instagram may ask for a video selfie or other details to confirm you own the account.</p>'
   '<p>Use an email address that only you can read when it asks for contact details, and use a device and network you normally use. Meta doesn’t publish a timeline for these checks, so wait for the email Instagram sends rather than starting a second request.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t pay a “2FA unlock” service</strong> that asks for your password or a code. A real helper never needs the code that was texted to you.</li><li><strong>Don’t forward a code</strong> to anyone who messages you, even a friend. Takeovers often start with a hijacked friend’s chat.</li><li><strong>Don’t create a second account</strong> and report the first as hacked. That splits your followers and does not unlock anything.</li><li><strong>Don’t tap “Trust this device”</strong> on a shared or public device.</li></ul>'),
  ('after', 'Once you are back in',
   '<p>Save a fresh set of backup codes somewhere other than the phone itself. Add an authentication app, keep the text-message number current, and update the email on the account. If you change phones often, make the move part of the routine: set up the app on the new phone before wiping the old one.</p>')],
 [('Can Instagram turn off two-factor authentication for me?', 'Instagram’s help pages describe fixing it yourself with a backup code or a logged-in device. If neither is possible, the official recovery flow at instagram.com/hacked is the route to ask for help.'),
  ('How many backup codes do I get?', 'Instagram shows a short list, and you can get a new set from Accounts Center while you are logged in. Getting a new set cancels the old one.'),
  ('Is it safe to use a text-message code on a new number?', 'Yes, once you have changed the number in Accounts Center. An authentication app is more resilient because it doesn’t depend on a phone number.'),
  ('What if I see “try again later” while requesting codes?', 'Stop and wait. Meta doesn’t publish a timeline for these limits, so repeated requests only prolong it. Try once from a device you’ve used before.')],
 [IG_HACKED, ('Instagram Help: Securing your account with two-factor authentication', 'https://help.instagram.com/566810106808145'), ('Instagram Help: How to use a backup code', 'https://help.instagram.com/1006568999411025'), IG_HELP],
 [('/guides/hacked-instagram-account-recovery/', 'Hacked Instagram account recovery'), ('/guides/instagram-account-locked/', 'Instagram account locked'), ('/guides/instagram-lost-access-to-email-or-phone/', 'Lost access to your Instagram email or phone')],
 ['/guides/hacked-instagram-account-recovery/', '/guides/instagram-account-locked/'],
 'I lost my Instagram two-factor codes and can’t log in. Can you help?', 'Instagram two-factor lockout',
 ('Locked out by 2FA?', 'Send us what you still have', 'Tell us the username and what you can still reach, such as an old device or an email. We’ll point you to the right official route. No passwords, ever.'),
 ('Still can’t get in?', 'Let’s sort the recovery route together', 'Message us the username and a screenshot of the screen you’re stuck on. We work through Instagram’s official tools and never ask for your login or codes.'),
 pill='Lost Instagram two-factor codes'))

A(mk('instagram-lost-access-to-email-or-phone',
 'Lost access to the email or phone on your Instagram account',
 'Lost Access to Your Instagram Email or Phone?',
 'Can’t get into the email or number on your Instagram account? How to recover it, update your details and use Instagram’s official recovery routes.',
 'instagram', 'Access', 'Instagram',
 'recover the email or number first, if you can, then use Instagram’s login link. If that’s impossible, use the official recovery page at instagram.com/hacked.',
 'An old email address you stopped checking or a phone number you gave up is the most common reason people get stuck. Instagram sends reset links to those two places, so the real job is to find another way to prove the account is yours.',
 [('first', 'What to do first',
   '<p>Work out whether you are <strong>still logged in anywhere</strong>. If Instagram is open on an old phone, a tablet or a browser, you can update your email and number right now, before anything else breaks. Do that first and the problem goes away.</p>'
   '<p>If you’re logged out everywhere, write down every email address and phone number you might have used to sign up, including school, work and old numbers. You will try them in a moment.</p>'),
  ('s1', 'Step 1: Recover the email account itself',
   '<p>It is often easier to get an old mailbox back than to argue with a social app. Gmail, Outlook, Yahoo and others all have their own recovery pages, and a recovered mailbox lets Instagram’s normal login link work. Check the spam folder too. Instagram’s security messages come from addresses on Meta’s own domains, including mail.instagram.com.</p>'
   '<p>If you used a work or school address, ask the administrator whether the mailbox still exists.</p>'),
  ('s2', 'Step 2: Try every login you might have used',
   '<p>On the login screen you can enter a username, email or phone number. Try each. If you can’t remember your username, logging in with the email or phone usually shows it on your profile afterward. A friend can also open your profile and tell you the exact handle.</p>'),
  ('s3', 'Step 3: Ask for a login link',
   '<p>Tap <strong>Forgot password?</strong>, enter the username, email or phone, and choose <em>Send login link</em>. Instagram sends the link to the contact details it has on file. If neither is reachable, look for the option to say you can’t access them and follow the on-screen instructions.</p>'),
  ('s4', 'Step 4: Use the official recovery page',
   '<p>Instagram directs people who have lost access to both contact methods to its recovery page at instagram.com/hacked. It may ask you to enter a secure email address that only you can read, then send you a code or ask for a video selfie. Do it on a device you have used with Instagram before and complete the request once. Meta doesn’t publish a timeline, so wait for its reply before trying again.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t hand your login to a “recovery agent”</strong> who contacts you first. Offers to “reset the email for you” are the standard scam.</li><li><strong>Don’t reuse a throwaway email</strong> for the recovery request. Use one you will still own in a year.</li><li><strong>Don’t keep resubmitting</strong> the form. Duplicate requests can reset the check.</li></ul>'),
  ('after', 'After you are back in',
   '<p>Add a second email and a current phone number in Accounts Center, so one lost mailbox never locks you out again. Remove contact details you no longer control, and note that Instagram asks you to confirm any change through a link sent to the new address.</p>')],
 [('Can I log in to Instagram without my email and phone?', 'Only if you are still logged in on a device or can use a backup code. Otherwise, Instagram’s recovery page is the official route.'),
  ('What if my old phone number was reassigned to someone else?', 'Remove it from the account as soon as you can, because a new owner of that number could receive texts. If you’re locked out, tell Instagram through the recovery flow.'),
  ('Does it matter which device I use?', 'Yes. Using a device and network you normally use helps Instagram recognise you.')],
 [IG_HACKED, ('Instagram Help: Lost access to your email or phone number', 'https://help.instagram.com/358911864194456'), ('Instagram Help: Update your personal information', 'https://help.instagram.com/356648689595660')],
 [('/guides/hacked-instagram-account-recovery/', 'Hacked Instagram account recovery'), ('/guides/instagram-change-email-or-phone-securely/', 'Change your Instagram email or phone'), ('/hacker-changed-my-instagram-email-and-password/', 'Hacker changed email and password')],
 ['/guides/hacked-instagram-account-recovery/'],
 'I lost access to the email and phone on my Instagram account and need help getting back in', 'Instagram email and phone access lost',
 ('Both contacts gone?', 'Tell us what you still have', 'Send us the username and any email or number you used. We’ll help you pick the right official recovery route. No password needed.'),
 ('Need a hand?', 'We’ll walk the recovery route with you', 'Message us the username and a screenshot of where you’re stuck. We use official tools only and never ask for your password or codes.'),
 pill='Lost your Instagram email or phone'))

A(mk('instagram-suspicious-login-alert',
 'Instagram says there was a new login: what to do if it wasn’t you',
 'Instagram Suspicious Login Alert: What to Do',
 'Got a “was this you?” alert or a new-login email from Instagram? How to check it, secure the account and avoid fake security messages.',
 'instagram', 'Security', 'Instagram',
 'open the Instagram app yourself (not the email link), review where you’re logged in, log out unknown sessions and change your password.',
 'A new-login alert is the one moment you still have full control. You can see the logins, end the ones you don’t know and lock the door. People who wait until the password stops working have a much longer road back.',
 [('first', 'What to do first',
   '<p>Don’t tap the link in the alert. Open the Instagram app or website directly. Then check whether you can still log in. If you can, work through the steps below in order. If your password no longer works, go straight to the hacked-account guide instead.</p>'),
  ('s1', 'Step 1: Confirm the alert is real',
   '<p>Fake alerts are common. In the app you can review the recent emails Instagram has sent to you, found in the Meta Account or Accounts Center security area under <em>Recent emails</em>. Security emails from the last 14 days appear there. If the message you received isn’t listed, treat it as phishing and ignore its links.</p>'),
  ('s2', 'Step 2: Review where you’re logged in',
   '<p>In Accounts Center, open <em>Password and security</em> and then <em>Where you’re logged in</em>. You will see devices, locations and times. A familiar phone in the right city is fine. Log out of anything you don’t recognise. Location is approximate and can show a nearby city or your mobile carrier’s hub, so look at the device type and the time too.</p>'),
  ('s3', 'Step 3: Change your password and turn on two-factor authentication',
   '<p>Pick a password you use nowhere else. Then switch on two-factor authentication, ideally with an authentication app, and save the backup codes. Instagram’s own hacked-account page lists these steps as the first things to do if you can still log in.</p>'),
  ('s4', 'Step 4: Check what could be attached to the account',
   '<ul><li>Confirm the email and phone number in your settings are yours.</li><li>Check Accounts Center for linked accounts you don’t recognise.</li><li>Revoke third-party apps you no longer use.</li><li>If it’s a business account, check linked Pages and ad accounts for changes.</li></ul>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t reply to the “security team” DM or email</strong> asking you to “verify” with your password or a code.</li><li><strong>Don’t log in through a link in a message</strong> to “cancel” a login. Open the app yourself.</li><li><strong>Don’t keep using the same password</strong> on other sites. Change those too if you reused it.</li><li><strong>Don’t ignore it</strong> because nothing seems to have changed. Some takeovers wait before acting.</li></ul>'),
  ('help', 'If the password stops working',
   '<p>If you’re logged out and the details have changed, use instagram.com/hacked and the steps in our hacked Instagram recovery guide. Check your old email for a message from Instagram about the change, because it usually includes a link to undo it.</p>')],
 [('Does a new-login alert mean I’ve been hacked?', 'Not necessarily. It can be you on a new phone, a travel login or a VPN. But if you don’t recognise it, treat it as real and secure the account.'),
  ('Can I see which devices have my account?', 'Yes. Accounts Center shows where you’re logged in, with devices and approximate locations, and lets you log out remotely.'),
  ('Is a password reset email I didn’t request dangerous?', 'It usually means someone typed your username or email on the reset screen. If you don’t click it, nothing changes, but check your recent logins and consider turning on two-factor authentication.')],
 [IG_HACKED, ('Instagram Help: Review recent emails sent from Instagram', 'https://help.instagram.com/760602221058803/'), ('Instagram Help: If you think your profile has been hacked', 'https://help.instagram.com/149494825257596'), IG_HELP],
 [('/guides/hacked-instagram-account-recovery/', 'Hacked Instagram account recovery'), ('/guides/instagram-fake-ban-or-copyright-emails/', 'Fake Instagram ban emails'), ('/guides/instagram-two-factor-lost-access/', 'Lost Instagram two-factor codes')],
 ['/guides/hacked-instagram-account-recovery/'],
 'I got a suspicious Instagram login alert and want to make sure my account is secure', 'Instagram suspicious login',
 ('Not sure it’s safe?', 'Send us the alert', 'Forward a screenshot of what you received and we’ll tell you what we think it is and what to do next. We never need your password.'),
 ('Locked out already?', 'We’ll help you recover it', 'If the password no longer works, message us the username and when you noticed. We’ll point you to the official recovery route.'),
 pill='Instagram suspicious login alert'))

A(mk('instagram-fake-ban-or-copyright-emails',
 'Fake Instagram ban and copyright emails: how to spot them',
 'Fake Instagram Ban or Copyright Emails: Spot Them',
 'Got an email saying your Instagram will be deleted for copyright or policy reasons? How to check it’s real and what to do if you already clicked.',
 'instagram', 'Phishing', 'Instagram',
 'open Instagram yourself and check the app’s recent emails list. If the message isn’t in the app, it’s a scam and your account has not been banned.',
 'Phishing emails pretending to be Instagram copyright, ban or verification teams are some of the most common ways accounts get taken. They work because the threat is urgent and the page looks right. They are easy to check once you know where.',
 [('first', 'What to do first',
   '<p>Do not click anything in the message. Close it, open the Instagram app yourself, and look at the account status and the app’s list of recent emails. A real notice about your account will also appear inside the app, usually with an option to appeal there.</p>'),
  ('s1', 'Step 1: Check Instagram’s list of recent emails',
   '<p>In the app go to Settings and look for <em>Recent emails</em> in the Meta Account or Accounts Center security area. Security emails from the past 14 days are listed under <em>Security</em>. Instagram’s help page says to treat a message that isn’t listed there as suspect.</p>'),
  ('s2', 'Step 2: Look for the usual red flags',
   '<ul><li>A deadline of 24 or 48 hours, or a threat to delete the account.</li><li>A button that opens a form asking for your <strong>password, login code or card details</strong>.</li><li>A link to a domain that isn’t one of Instagram’s own, even if the text looks right.</li><li>A “copyright violation” with no image, post or link identifying what was reported.</li><li>An offer to keep or verify the badge for a fee.</li></ul>'),
  ('s3', 'Step 3: If you already clicked or typed anything',
   '<p>If you entered a password, change it immediately from the app and log out of other sessions. Turn on two-factor authentication. If you entered a login code, treat the account as compromised and check Accounts Center. If the password no longer works, use instagram.com/hacked and follow the steps in our hacked-account guide.</p>'),
  ('s4', 'Step 4: Report the message',
   '<p>Forward phishing emails to Meta using the address in Instagram’s phishing page, and report the DM or profile inside the app. If a genuine copyright claim exists, Instagram’s notice tells you what was removed and how to appeal.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t “appeal” on the page the email links to.</strong> Real appeals happen inside Instagram.</li><li><strong>Don’t pay a badge or verification fee</strong> to someone who contacted you first.</li><li><strong>Don’t assume it’s real because it uses your username</strong> or follower count. Scammers pull those from your profile.</li></ul>'),
  ('after', 'Staying ahead of it',
   '<p>Add two-factor authentication, keep your contact details current, and tell your team if you run a business account. Anyone with access can be tricked, so agree that nobody enters credentials from a link.</p>')],
 [('How can I tell a real Instagram email?', 'Check it against the Recent emails list inside the app. If it isn’t there, don’t trust it, whoever it claims to be from.'),
  ('Does a copyright email mean I’m banned?', 'Not by itself. A real copyright notice names the content and gives an appeal route inside Instagram. A fake one threatens deletion and asks for a login.'),
  ('I clicked a link but entered nothing. Am I safe?', 'Probably, but check Accounts Center for unfamiliar logins and change your password to be safe.')],
 [('Instagram Help: Review recent emails sent from Instagram', 'https://help.instagram.com/760602221058803/'), IG_HACKED, ('Instagram Community Guidelines', 'https://help.instagram.com/477434105621119'), IG_HELP],
 [('/guides/instagram-suspicious-login-alert/', 'Instagram suspicious login alert'), ('/guides/hacked-instagram-account-recovery/', 'Hacked Instagram account recovery'), ('/guides/instagram-account-disabled/', 'Instagram account disabled')],
 ['/guides/instagram-account-disabled/', '/guides/hacked-instagram-account-recovery/'],
 'I got an email saying my Instagram will be banned and I want to check if it is real', 'Is this Instagram email real',
 ('Not sure it’s real?', 'Send us a screenshot', 'We’ll tell you what we think it is and what to do next. Don’t forward any codes or passwords, only a screenshot.'),
 ('Already clicked?', 'Let’s check the account', 'Message us the username and what you entered. We’ll point you to the official steps to secure it.'),
 pill='Fake Instagram ban emails'))

A(mk('instagram-download-your-data-backup',
 'How to download your Instagram data before something goes wrong',
 'How to Download Your Instagram Data (Backup)',
 'Back up your Instagram posts, messages and followers while you can still log in. How the download tool works and what it won’t restore.',
 'instagram', 'Backup', 'Instagram',
 'go to Accounts Center, open “Download your information”, pick your profile and a format, and save the file somewhere safe. You need to be logged in to do it.',
 'The best time to back up an Instagram account is before anyone disables it. A download won’t bring a banned account back, but it saves your photos, videos and messages, and it helps you prove what the account contained.',
 [('first', 'What to do first',
   '<p>Decide what you need. For a hobby account that is usually photos and videos. For a business it’s also customer messages, comments, follower lists and ad data. Choose <strong>everything</strong> if you are unsure, then trim later.</p>'),
  ('s1', 'Step 1: Open the download tool',
   '<p>Go to Accounts Center, then <em>Your information and permissions</em>, then <em>Download your information</em>. You may see this under <em>Export your information</em> depending on your version. Pick <em>Create export</em> and choose your Instagram profile.</p>'),
  ('s2', 'Step 2: Choose what to include',
   '<p>You can pick all information or specific types such as posts, stories, messages or followers. Set a date range, then choose the format. <strong>HTML</strong> is easier to browse, while <strong>JSON</strong> is better if you need to move data into another tool. Choose a media quality that matches your needs, since higher quality means a larger file.</p>'),
  ('s3', 'Step 3: Download it safely',
   '<p>Meta emails you when the file is ready. Download it only through the link in the Accounts Center notification and not through links in unexpected messages. The file contains private messages and personal data, so store it somewhere protected, with a password if your device allows.</p>'),
  ('s4', 'Step 4: Back up what the download misses',
   '<ul><li>Your own original photos and videos, stored on your phone or cloud storage.</li><li>A list of the accounts you collaborate with and a way to reach them outside Instagram.</li><li>Your caption and hashtag library.</li><li>An email or newsletter list so you can reach followers if the account disappears.</li></ul>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t wait until you’re locked out.</strong> The tool needs you to be logged in, and once an account is deleted it’s gone.</li><li><strong>Don’t share the file</strong> with strangers or upload it to a random site. It includes private chats.</li><li><strong>Don’t expect it to restore the account.</strong> It is a record, not a rollback.</li></ul>'),
  ('after', 'Making it a habit',
   '<p>Request a fresh export every few months, and before any big change such as a username change, an account switch or a long period away. Date the files so you know which is newest.</p>')],
 [('Does a data download restore a banned account?', 'No. It gives you a copy of your content, but it doesn’t reinstate the account.'),
  ('Can I download data from a disabled account?', 'The tool normally needs you to log in, so a disabled account may not be able to. That’s why a backup made earlier matters.'),
  ('How long does the download take?', 'It depends on the amount of data. Meta emails you when the file is ready, and doesn’t publish an exact time.')],
 [('Instagram Help: Permanently delete or deactivate your profile (includes export guidance)', 'https://help.instagram.com/370452623149242/delete-your-account'), IG_HELP],
 [('/guides/protect-your-business-from-an-instagram-ban/', 'Protect your business from an Instagram ban'), ('/guides/instagram-account-disabled/', 'Instagram account disabled'), ('/guides/instagram-deactivate-or-delete-account/', 'Deactivate or delete Instagram')],
 ['/guides/instagram-account-disabled/'],
 'I want to back up my Instagram account and need help planning for the worst', 'Instagram backup help',
 ('Protect your account', 'Want a second pair of eyes?', 'Send us the account type and what matters most to you, and we’ll suggest a simple backup and access plan.'),
 ('Already disabled?', 'We can help from here', 'If your account is already disabled and you never backed up, message us. We’ll tell you which official routes are still open.'),
 pill='Back up your Instagram data'))

A(mk('instagram-cant-log-in-password-incorrect',
 'Instagram says the password is wrong (and it isn’t): fixes that work',
 'Instagram Password Incorrect But It’s Right? Fixes',
 'Instagram rejects your password or says it can’t find your account? Check the username, reset with a login link and spot a disabled or suspended message.',
 'instagram', 'Login', 'Instagram',
 'check you’re entering the username (not the display name), try your email or phone, then reset with a login link. If it says disabled or suspended, that’s a different problem.',
 'Login errors look alike but mean different things. “Incorrect password”, “can’t find your account”, “try again later” and “your account was disabled” each call for a different fix. Read the exact message first.',
 [('first', 'What to do first',
   '<p>Write down the <strong>exact wording</strong> of the error. “Your account has been disabled” and “we suspended your account” belong in our disabled and suspended guides. Anything about passwords, codes or “try again later” belongs here.</p>'),
  ('s1', 'Step 1: Check the basics',
   '<ul><li>Use your <strong>username</strong>, not your display name. If you’re unsure, try your email or phone number instead.</li><li>Check capital letters and the keyboard language.</li><li>Update the Instagram app and restart it.</li><li>Try the web version at instagram.com in a private window.</li><li>Don’t use a saved autofill that may hold an old password.</li></ul>'),
  ('s2', 'Step 2: Reset with a login link',
   '<p>Tap <strong>Forgot password?</strong> and ask for a login link to your email or phone. The link works on any device. Look in spam and promotions folders, and add the address Instagram uses to your safe list. If the email never arrives, make sure you typed it with the exact spelling you registered.</p>'),
  ('s3', 'Step 3: Try the Facebook login',
   '<p>If you once used “Continue with Facebook”, that is probably still how the account signs in. Try it, and check the Facebook account you were logged into at the time.</p>'),
  ('s4', 'Step 4: If it keeps failing',
   '<p>Meta doesn’t publish a timeline for repeated-attempt limits. Wait, stop retrying, and try from a device and network you have used for Instagram before. If you suspect someone changed your password, follow the steps in our hacked Instagram recovery guide.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t try dozens of passwords quickly.</strong> It can trigger a temporary block.</li><li><strong>Don’t use a “password cracking” or “account finder” service.</strong> They are scams and some steal your details.</li><li><strong>Don’t create a new account</strong> before you’ve tried the login link.</li></ul>'),
  ('help', 'When it’s not a password problem',
   '<p>If the message says your account is disabled, suspended, locked or restricted, the login isn’t the issue. Use the matching guide below, since each has its own appeal route.</p>')],
 [('Why does Instagram say my password is wrong?', 'You may be using an old password, the wrong username or a different login method. A login link sidesteps the problem by letting you set a new password.'),
  ('Why am I not getting the reset email?', 'Check spam, make sure the address is the one on the account, and wait a few minutes. If you no longer have it, see our guide on lost access to your email or phone.'),
  ('Does “try again later” mean I’m banned?', 'No. It usually means too many attempts. Wait and try once from a device you’ve used before.')],
 [IG_HACKED, ('Instagram Help: What to do if you forget your username', 'https://help.instagram.com/1645522102409931'), IG_HELP],
 [('/guides/instagram-lost-access-to-email-or-phone/', 'Lost your Instagram email or phone'), ('/guides/instagram-account-locked/', 'Instagram account locked'), ('/guides/instagram-account-disabled/', 'Instagram account disabled')],
 ['/guides/instagram-account-locked/'],
 'I can’t log in to Instagram, it says my password is wrong, and I need help', 'Instagram login trouble',
 ('Still locked out?', 'Tell us what the screen says', 'Send the exact message and the username. We’ll tell you which route fits and what to try next.'),
 ('Ready for help?', 'Let’s get you back in', 'Message us the username and a screenshot of the login error. We use official tools and never ask for your password.'),
 pill='Instagram password incorrect'))

A(mk('instagram-change-email-or-phone-securely',
 'How to change your Instagram email or phone number safely',
 'Change Your Instagram Email or Phone Safely',
 'Changing the email or number on your Instagram account? Add the new one first, confirm it, then remove the old, and check nothing was changed behind your back.',
 'instagram', 'Security', 'Instagram',
 'add and confirm the new email or number first, then remove the old one. Instagram needs at least one confirmed contact method at all times.',
 'The email and phone number on your Instagram account are the keys to recovery. Change them in the wrong order and you can lock yourself out. Change them without noticing an unfamiliar change and you can lose the account.',
 [('first', 'What to do first',
   '<p>Make sure you have access to <strong>both</strong> the old and the new contact. Instagram sends a confirmation to the new address, and the old address receives a notice that lets you reverse a change you didn’t make. Keep the old inbox open until you’re sure everything is correct.</p>'),
  ('s1', 'Step 1: Add the new email or number',
   '<p>Open your profile, then Settings, then Accounts Center, then <em>Profiles and personal details</em> and <em>Contact info</em>. Choose <em>Add new contact</em>, enter the email or phone, and confirm it with the code Instagram sends. Don’t remove anything yet.</p>'),
  ('s2', 'Step 2: Remove the old one',
   '<p>Once the new contact is confirmed, select the old email or phone and choose Remove or Delete. Instagram only lets you remove an email if a confirmed phone number remains, and vice versa, so you can’t strip both by accident.</p>'),
  ('s3', 'Step 3: Update two-factor authentication',
   '<p>The number used for text-message codes is a separate setting. Under Accounts Center, <em>Password and security</em> and <em>Two-factor authentication</em>, switch to the new number and save the new backup codes. An authentication app avoids this problem next time.</p>'),
  ('s4', 'Step 4: Check Instagram’s emails to you',
   '<p>Look at the list of recent emails in the app to confirm the changes you made, and nothing else. If an email says your address was changed and you didn’t do it, the message to your old address includes a link to secure the account. Use it quickly and then change your password.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t switch to a shared or work email</strong> you might lose when you change jobs.</li><li><strong>Don’t give a recovery email to anyone</strong> else managing the account, such as an agency. Use roles and tools meant for sharing access instead.</li><li><strong>Don’t keep a number you no longer own</strong> as a contact, since the next owner could receive your codes.</li></ul>'),
  ('after', 'A simple standard to follow',
   '<p>Keep one email you control for good and one current phone number. Review them every few months and after any time you change phone plans. That one habit prevents most recovery problems.</p>')],
 [('Can I change my Instagram email without logging in?', 'No. You have to be logged in. If you’re locked out, use Instagram’s recovery routes instead.'),
  ('Why can’t I remove my old email?', 'Instagram needs at least one confirmed contact method. Add and confirm a new one first.'),
  ('Someone changed my email. What now?', 'Check your old inbox for a message from Instagram with a link to secure the account, then follow our hacked-account guide.')],
 [('Instagram Help: Update your name, email and other personal information', 'https://help.instagram.com/356648689595660'), ('Instagram Help: What to do if the email for your account was changed', 'https://help.instagram.com/1682636905358680'), IG_HELP],
 [('/guides/instagram-lost-access-to-email-or-phone/', 'Lost your Instagram email or phone'), ('/guides/instagram-two-factor-lost-access/', 'Lost Instagram two-factor codes'), ('/guides/hacked-instagram-account-recovery/', 'Hacked Instagram account recovery')],
 ['/guides/hacked-instagram-account-recovery/'],
 'I need to change the email or phone number on my Instagram without losing the account', 'Change Instagram contact details',
 ('Worried about locking yourself out?', 'Ask us before you remove anything', 'Tell us what you’re changing and why. We’ll help you check the order so you don’t get stuck.'),
 ('Already changed something?', 'Let’s make sure it’s secure', 'If an email or number changed without you, message us the username. We’ll point you to the official recovery route.'),
 pill='Change your Instagram email or phone'))

A(mk('instagram-id-verification-request',
 'Instagram asked for your ID: what’s accepted and how to submit it safely',
 'Instagram Asked for ID? What’s Accepted & Safe',
 'Instagram asking you to upload an ID or confirm your identity? Which documents it accepts, how your ID is handled and how to avoid fake ID requests.',
 'instagram', 'Verification', 'Instagram',
 'upload only inside the Instagram screen that asked for it. Instagram accepts one government photo ID or two other documents, and your name and photo or date of birth must match.',
 'An ID request can feel alarming, especially when you’re already locked out. It is a normal part of confirming identity or age. It’s also a favourite hook for scammers, so the first question is whether the request is real.',
 [('first', 'What to do first',
   '<p>Make sure the request <strong>appears inside the Instagram app or on instagram.com</strong> when you log in or follow an official recovery link. If it arrived by DM, text or an email you can’t match to the app’s list of recent emails, don’t upload anything.</p>'),
  ('s1', 'Step 1: Read why you’re being asked',
   '<p>Instagram may ask for ID to confirm your identity after a lock, to check your age, or as part of an appeal. The screen tells you which. The reason matters because it tells you whether a video selfie, a photo ID or both are expected.</p>'),
  ('s2', 'Step 2: Pick an accepted document',
   '<p>Instagram’s help page lists the accepted types. In general you can send one government-issued photo ID, or if you don’t have one, two non-government documents. At least one should show your photo and age or date of birth, and the name should match the account. Check the live list on the help page, because acceptable documents vary by country.</p>'),
  ('s3', 'Step 3: Take a clear photo',
   '<ul><li>Use good light and a plain surface.</li><li>Keep all four corners of the document in frame.</li><li>Avoid glare and shadows over text and the photo.</li><li>Don’t edit or crop the image beyond what the screen asks for.</li></ul>'),
  ('s4', 'Step 4: Submit once and wait',
   '<p>Upload through the official screen, then wait for Instagram’s response by email and in the app. Meta doesn’t publish a timeline. Instagram says it stores IDs securely, keeps them private from other users, and deletes the copy within a set period after the check. Read the current wording on the help page so you know what applies in your region.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t send your ID to a person</strong> who says they work for Instagram, in DMs or by email.</li><li><strong>Don’t use someone else’s ID</strong> or a fabricated one. It’s against the rules and can end the appeal.</li><li><strong>Don’t resubmit many times</strong> if the first upload is still processing.</li></ul>'),
  ('help', 'If the upload fails or is rejected',
   '<p>Try again once with a clearer photo, on the same device, with the latest app. If the account name differs from your ID, explain this in any text box on the form. Keep in mind that a rejection can often be followed by a new submission if the screen offers one.</p>')],
 [('Will Instagram share my ID with others?', 'Instagram says IDs are stored securely and aren’t shown to other users. Read the help page for the current retention details.'),
  ('Do I need a government ID?', 'Not always. If you have none, Instagram accepts two non-government documents, as long as the details match and at least one shows your photo or date of birth.'),
  ('Is it safe to send my ID to someone who offers to help?', 'No. Only upload to Instagram’s own screen. A helper never needs your ID to be sent to them.')],
 [('Instagram Help: Types of ID Instagram accepts', 'https://help.instagram.com/271237319690904/'), ('Instagram Help: Why you’re being asked to upload an ID', 'https://help.instagram.com/293775921768331/'), ('Instagram Help: Video selfie verification', 'https://help.instagram.com/1053588012132894')],
 [('/guides/instagram-video-selfie-verification/', 'Instagram video selfie verification'), ('/guides/instagram-account-suspended-appeal/', 'Instagram account suspended'), ('/instagram-account-suspended-age-verification/', 'Suspended for age verification')],
 ['/guides/instagram-video-selfie-verification/'],
 'Instagram asked me for ID and I want to check it is real before I submit', 'Instagram ID request',
 ('Not sure it’s real?', 'Show us the screen', 'Send a screenshot of the request (not your ID) and we’ll tell you if it looks like the official flow.'),
 ('Stuck on verification?', 'We’ll help with the next step', 'Message us the username and what Instagram asked for. We help you submit through the official route and never ask for your login.'),
 pill='Instagram asked for your ID'))
